class LLMPreferenceDataset(torch.utils.data.Dataset):

    def __init__(self, df, tokenizer, max_len=512):
        self.df = df
        self.tokenizer = tokenizer
        self.max_len = max_len
        self.texts = []
        for str, row in df.iterrows():
            text = f"Prompt: {row['prompt']}\n\nResponse A: {row['response_a']}\n\nResponse B: {row['response_b']}"
            text = re.sub('\\s+', ' ', text).strip()
            self.texts.append(text)
        self.labels = df['label'].tolist() if 'label' in df.columns else None

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):
        text = self.texts[idx]
        if not isinstance(text, str) or len(text) == 0:
            text = ' '
        try:
            inputs = self.tokenizer(text, max_length=self.max_len, padding='max_length', truncation=True, return_tensors='pt')
            inputs = {k: v.squeeze(0) for k, v in inputs.items()}
            if self.labels is not None:
                inputs['labels'] = torch.tensor(self.labels[idx], dtype=torch.long)
            return inputs
        except Exception as e:
            print(f'警告：处理索引{idx}时出错：{str(e)}')
            print(f'问题文本（前100字符）：{repr(text[:100])}')
            cleaned_text = re.sub('[^\\x00-\\x7F]+', '', text)
            cleaned_text = cleaned_text[:1000]
            inputs = self.tokenizer(cleaned_text, max_length=self.max_len, padding='max_length', truncation=True, return_tensors='pt')
            inputs = {k: v.squeeze(0) for k, v in inputs.items()}
            if self.labels is not None:
                inputs['labels'] = torch.tensor(self.labels[idx], dtype=torch.long)
            return inputs

